/** Maps the semantic roles onto Material 3 so stock components look like Brasscribe. */
fun BrasscribeColors.toColorScheme(dark: Boolean): ColorScheme {
    val scheme = if (dark) darkColorScheme() else lightColorScheme()
    return scheme.copy(
        primary = primary, onPrimary = onPrimary,
        primaryContainer = secondary, onPrimaryContainer = onSecondary, inversePrimary = brass,
        secondary = text, onSecondary = bg,
        secondaryContainer = secondary, onSecondaryContainer = onSecondary,
        tertiary = brassText, onTertiary = onPrimary,
        tertiaryContainer = brassTint, onTertiaryContainer = text,
        background = bg, onBackground = text,
        surface = bg, onSurface = text, surfaceVariant = surface, onSurfaceVariant = textMuted,
        surfaceTint = bg, inverseSurface = text, inverseOnSurface = bg,
        error = error, onError = bg, errorContainer = surface, onErrorContainer = error,
        outline = borderStrong, outlineVariant = border, scrim = Color.Black,
        surfaceBright = surfaceRaised, surfaceDim = surface,
        surfaceContainerLowest = surfaceRaised, surfaceContainerLow = surfaceRaised,
        surfaceContainer = surface, surfaceContainerHigh = surfaceRaised, surfaceContainerHighest = secondary,
    )
}

/** The type ramp as Material 3 roles. Sizes are sp, so they follow the system font scale. */
fun brasscribeTypography(display: FontFamily = FontFamily.Serif): Typography {
    val base = Typography()
    return base.copy(
        displaySmall = base.displaySmall.copy(fontFamily = display, fontWeight = FontWeight.Normal, fontSize = 36.sp, lineHeight = 44.sp, letterSpacing = -0.2.sp),
        headlineMedium = base.headlineMedium.copy(fontFamily = FontFamily.Default, fontWeight = FontWeight.SemiBold, fontSize = 28.sp, lineHeight = 36.sp, letterSpacing = 0.sp),
        titleLarge = base.titleLarge.copy(fontFamily = FontFamily.Default, fontWeight = FontWeight.SemiBold, fontSize = 22.sp, lineHeight = 28.sp, letterSpacing = 0.sp),
        titleMedium = base.titleMedium.copy(fontFamily = FontFamily.Default, fontWeight = FontWeight.SemiBold, fontSize = 16.sp, lineHeight = 24.sp, letterSpacing = 0.sp),
        bodyLarge = base.bodyLarge.copy(fontFamily = FontFamily.Default, fontWeight = FontWeight.Normal, fontSize = 16.sp, lineHeight = 24.sp, letterSpacing = 0.sp),
        bodyMedium = base.bodyMedium.copy(fontFamily = FontFamily.Default, fontWeight = FontWeight.Normal, fontSize = 14.sp, lineHeight = 20.sp, letterSpacing = 0.sp),
        labelLarge = base.labelLarge.copy(fontFamily = FontFamily.Default, fontWeight = FontWeight.SemiBold, fontSize = 16.sp, lineHeight = 24.sp, letterSpacing = 0.sp),
        bodySmall = base.bodySmall.copy(fontFamily = FontFamily.Default, fontWeight = FontWeight.Normal, fontSize = 12.sp, lineHeight = 16.sp, letterSpacing = 0.sp),
    )
}

